export type ReadOnlyChange = { 
/**
 * The tree-relative path, scrubbed; `HEAD`, `refs` or `index` for a
 * change of the repository state.
 */
path: string, 
/**
 * `modified`, `added`, `deleted`, `mode`, `link`, `git_head`,
 * `git_refs` or `git_index`. Free text, so a kind a newer apb adds
 * still reads.
 */
change: string, };

export type ReadOnlyViolation = { changes: Array<ReadOnlyChange>, 
/**
 * Changed paths left out of `changes`.
 */
truncated?: number, 
/**
 * The run-relative evidence file.
 */
evidence?: string, };

export type ReadOnlyRow = { node: string, 
/**
 * The list item the attempt ran, for an item of a list node.
 */
item?: string, attempt: number, 
/**
 * The changes that failed the node (`read_only_dirty`); absent while
 * none was seen.
 */
violated?: ReadOnlyViolation, tier: ReadOnlyTier, 
/**
 * Entries the before-state lists; 0 in the enforced tier.
 */
entries?: number, 
/**
 * Bytes the before-state hashed; 0 in the enforced tier.
 */
bytes?: number, 
/**
 * The limit that stopped it short (tier `detected_partial`).
 */
partial?: ReadOnlyLimit, };

export type Rate = { count: number, of: number, rate?: number, };

export type PerRun = { total: number, runs: number, per_run?: number, };

export type Waits = { count: number, median_ms?: number, max_ms?: number, };

export type Outcomes = { succeeded: number, failed: number, aborted: number, 
/**
 * Still running, paused, or ended without a terminal event.
 */
other: number, };

export type Spend = { 
/**
 * Runs whose attempts reported usage.
 */
runs_with_usage: number, 
/**
 * Input plus output tokens (cache reads and writes not included).
 */
tokens: PerRun, 
/**
 * Runs that reported a cost.
 */
runs_with_cost: number, 
/**
 * Finished attempts that reported a cost, over every finished attempt:
 * how much of the spend the cost figures cover.
 */
cost_known: Rate, 
/**
 * The reported costs of every run, whatever their basis;
 * `cost_by_basis` splits it.
 */
cost_usd: number, cost_per_run_usd?: number, 
/**
 * `cost_usd` split by what each figure is: billed, a subscription
 * equivalent nobody is billed, or of unknown basis.
 */
cost_by_basis?: CostByBasis, };

export type ModelUse = { 
/**
 * Attempts per model actually used ([`UNREPORTED`] when a host said
 * nothing).
 */
models: { [key in string]: number }, 
/**
 * Attempts whose model differs from the node profile's primary model.
 */
model_mismatch: number, };

export type GoalStats = { index: number, description: string, 
/**
 * `script`, `marker` or `manual`.
 */
check: string, 
/**
 * Runs that checked it.
 */
checked: number, passed: Rate, failed: number, 
/**
 * `error`: the check could not run.
 */
errors: number, manual: number, };

export type ExecutorQuality = { 
/**
 * The executor digest, shortened.
 */
executor: string, good: Rate, poor: Rate, graded_runs: number, };

export type QualityStats = { criterion: string, source: CriterionSource, 
/**
 * `<kind>/<version>`.
 */
grader: string, task_type: string, 
/**
 * The criterion definition's digest the levels were given under.
 */
digest: string, 
/**
 * Runs whose latest grade of the grader has the criterion.
 */
graded_runs: number, tally: Tally, 
/**
 * Good over determinate levels (good, partial, poor).
 */
good: Rate, 
/**
 * Poor over determinate levels.
 */
poor: Rate, 
/**
 * The levels per executor group, only when the criterion's subject is
 * a node and the graded runs bound it to more than one executor. A
 * breakdown only: the comparable key and promotion never read it.
 */
by_executor?: Array<ExecutorQuality>, };

export type QualityDelta = { criterion: string, grader: string, task_type: string, 
/**
 * The criterion definition's digest both versions graded under: a
 * criterion whose definition changed has one delta per digest.
 */
digest: string, good_delta?: number, poor_delta?: number, };

export type KindCount = { kind: string, occurrences: number, runs: number, };

export type FindingGroup = { kind: string, location: string, runs: number, occurrences: number, 
/**
 * The latest run that reported it.
 */
last_run: string, };

export type FindingStats = { by_kind: Array<KindCount>, 
/**
 * The most widespread groups, by runs, at most [`TOP_GROUPS`].
 */
top: Array<FindingGroup>, runs_with_warnings: Rate, };

export type BaselineStats = { check: string, observation: string, 
/**
 * Runs that compared it.
 */
compared: number, met: Rate, regressed: number, unknown: number, };

export type DigestStats = { 
/**
 * The profile digest, shortened.
 */
profile: string, 
/**
 * The bundle digest (profile plus skills), shortened.
 */
bundle: string, 
/**
 * The executor digest (chain, tiers, `ephemeral`), shortened; empty
 * only for a binding no manifest recorded.
 */
executor?: string, 
/**
 * The group is a run-local ephemeral override.
 */
ephemeral?: boolean, 
/**
 * Runs the node ran in under this executor.
 */
runs: number, 
/**
 * Runs where the node passed on its one visit and first attempt,
 * without a fallback.
 */
first_pass: Rate, duration: Waits, 
/**
 * The median tokens of a visit that reported usage on every attempt.
 */
tokens_per_visit?: number, };

export type ExecutorChange = { node: string, base_profile: string, against_profile: string, base_bundle: string, against_bundle: string, 
/**
 * The executor digests, shortened; empty only for a binding no
 * manifest recorded.
 */
base_executor?: string, against_executor?: string, };

export type StepStats = { 
/**
 * The binding snapshot's digest, shortened; `None` when not recorded.
 */
binding?: string, 
/**
 * The step index in its binding's chain; `None`: position not
 * recorded.
 */
step?: number, 
/**
 * `primary`, `fallback`, `tier`, `host_fallback` or `ephemeral`.
 */
source: string, 
/**
 * `cli`, `host` or `scenario`.
 */
executed_by: string, attempts: number, successes: Rate, median_attempt_ms?: number, 
/**
 * The reported cost of the step's finished attempts, summed like the
 * version's spend.
 */
cost_usd?: number, 
/**
 * Finished attempts that reported a cost, over every finished one.
 */
cost_known: Rate, 
/**
 * `cost_usd` split by basis: billed, a subscription equivalent nobody
 * is billed, or of unknown basis.
 */
cost_by_basis?: CostByBasis, 
/**
 * Attempts by reported model: `one:<model>`, `mixed`, `partial`,
 * `none`.
 */
reported_models: { [key in string]: number }, 
/**
 * Closes of the step by reason (the close reason's label).
 */
closes_by_reason: { [key in string]: number }, };

export type TransitionStats = { from_step?: number, to_step?: number, 
/**
 * The close reason's label, or [`NOT_RECORDED`].
 */
reason: string, count: number, };

export type HintFollow = { hinted: number, followed: number, not_followed: number, not_reported: number, };

export type ExecutorGroup = { 
/**
 * The profile digest, shortened.
 */
profile: string, 
/**
 * The bundle digest, shortened.
 */
bundle: string, 
/**
 * The executor digest, shortened.
 */
executor: string, 
/**
 * The group is a run-local ephemeral override.
 */
ephemeral: boolean, runs: number, attempts: number, steps: Array<StepStats>, transitions: Array<TransitionStats>, 
/**
 * Host groups only.
 */
hint_follow?: HintFollow, };

export type NodeStats = { node: string, 
/**
 * Runs with at least one execution of the node that was not cancelled
 * (an open one included). A finish without a prompt is an execution;
 * a `join: any` race loser is not counted here ([`NodeStats::cancelled`]).
 */
runs: number, 
/**
 * Runs the node is established to belong to: a known definition the
 * run executed declares it, or the run executed it. Counted once per
 * run across its definitions. A node no run executed has a row with
 * zero executions.
 */
in_runs: number, 
/**
 * Runs where only the final snapshot names the node and a definition
 * the run executed is not established: membership unknown, counted
 * apart from `in_runs`.
 */
in_runs_unknown: number, 
/**
 * Why the node did not run in the runs it belongs to but did not
 * execute in, one explanation per run, by class and code.
 */
not_run: Array<ReasonCount>, 
/**
 * Executions begun, race losers left out (`crate::identity`).
 */
executions: number, 
/**
 * Of those, the ones that ended.
 */
completed: number, 
/**
 * Of those, the ones still open: running, paused, or cut short.
 */
open: number, 
/**
 * Completed executions that ended `failed` or `timed_out`.
 */
failed: number, 
/**
 * Executions a `join: any` race cancelled, counted apart.
 */
cancelled: number, 
/**
 * Runs where the node's first result was a success on attempt 1, with
 * no retry, fallback or later re-entry.
 */
first_pass: Rate, retries: number, fallbacks: number, 
/**
 * Executions after the first in the same run (a loop back into it):
 * `executions - runs`, never negative.
 */
reentries: number, duration: Waits, 
/**
 * The declared `expected_duration`, in seconds.
 */
expected_s?: number, 
/**
 * Finished executions that took longer than `expected_s`.
 */
over_expected?: Rate, deliverable_missing: number, output_fields_missing: number, 
/**
 * Its figures per executor digest, when the runs of the version bound
 * it to more than one ([`digests`]).
 */
digests?: Array<DigestStats>, 
/**
 * Its figures per executor group, step and transition ([`executors`]).
 */
executors?: Array<ExecutorGroup>, 
/**
 * Attempts per model actually used ([`UNREPORTED`] when a host said
 * nothing).
 */
models: { [key in string]: number }, 
/**
 * Attempts whose model differs from the node profile's primary model.
 */
model_mismatch: number, };

export type KnownCount = { value: number, known_runs: number, runs: number, };

export type CategoryStats = { 
/**
 * `review`, `question`, `automatic`, `operator`, `supervisor_node`
 * or `supervisor_run`.
 */
category: string, 
/**
 * What `denominator` counts: `gate visits`, `questions asked`,
 * `decisions asked`, `runs` or `node executions`.
 */
unit: string, denominator: number, 
/**
 * The category's interventions (for `automatic`, the applied
 * decisions).
 */
count: KnownCount, 
/**
 * The count split by kind, option, surface or use.
 */
split: { [key in string]: KnownCount }, };

export type InterventionStats = { 
/**
 * Finished runs.
 */
runs: number, total: KnownCount, 
/**
 * Interventions per run over the runs where it is known.
 */
per_run_median?: number, per_run_mean?: number, 
/**
 * Runs without any intervention, over the runs where it is known.
 */
without_any: KnownCount, automatic_total: KnownCount, categories: Array<CategoryStats>, 
/**
 * The engine's own actions by kind, outside every total.
 */
engine: { [key in string]: number }, 
/**
 * Unknown supervisor action names, outside every total.
 */
other: { [key in string]: number }, 
/**
 * Actions that name no actor, outside every total.
 */
actor_unknown: { [key in string]: number }, };

export type ReviewCounts = { 
/**
 * Review requests: one per gate visit.
 */
visits: number, 
/**
 * Decisions through the review channel.
 */
channel: number, 
/**
 * Decisions the engine took: an enforced recommendation or the gate's
 * unattended outcome.
 */
automatic: number, 
/**
 * Requests a directive closed without a decision.
 */
withdrawn: number, 
/**
 * Requests still open.
 */
open: number, 
/**
 * Decisions an older binary wrote without saying who decided:
 * neither `channel` nor `automatic` is known for the run then.
 */
unattributed: number, 
/**
 * Decisions by option.
 */
options: { [key in string]: number }, 
/**
 * Channel decisions by the surface they came through; `not_recorded`
 * when the decision names none.
 */
via: { [key in string]: number }, };

export type QuestionCounts = { asked: number, 
/**
 * Answers by `answered_by`.
 */
answered: { [key in string]: number }, abandoned: number, };

export type UseCounts = { asked: number, applied: number, };

export type RunInterventions = { 
/**
 * The oldest apb that wrote the run, when every writer recorded one.
 */
writer?: string, 
/**
 * The writer records who decided every gate, every expedite and every
 * unattended answer ([`ATTRIBUTION_SINCE`]).
 */
attribution_known: boolean, reviews: ReviewCounts, questions: QuestionCounts, 
/**
 * Automatic decisions by use.
 */
automatic: { [key in string]: UseCounts }, 
/**
 * Operator actions by kind.
 */
operator: { [key in string]: number }, 
/**
 * Supervisor corrections aimed at one node, by kind.
 */
supervisor_node: { [key in string]: number }, 
/**
 * Supervisor corrections of the whole run, by kind.
 */
supervisor_run: { [key in string]: number }, 
/**
 * Node executions begun (race losers left out): the denominator of
 * the node-targeted corrections.
 */
node_executions: number, 
/**
 * Pauses, resumes, aborts and expedites that name no actor.
 */
actor_unknown: { [key in string]: number }, 
/**
 * The engine's own actions, never an intervention.
 */
engine: { [key in string]: number }, 
/**
 * Supervisor action names this binary does not know (a newer apb's),
 * never in a total.
 */
other: { [key in string]: number }, 
/**
 * Distinct list items the counted decisions belong to.
 */
items: number, 
/**
 * Interventions: channel decisions, human and supervisor answers,
 * operator actions and supervisor corrections. Unknown when a gate
 * decision is unattributed or an actor is unknown.
 */
total?: number, 
/**
 * Automatic decisions, automatic gate decisions and unattended answers;
 * unknown when a gate decision is unattributed.
 */
automatic_total?: number, };

export type VersionStats = { playbook: string, version: string, runs: number, outcomes: Outcomes, 
/**
 * Succeeded runs over finished runs (succeeded, failed, aborted).
 */
success: Rate, 
/**
 * Succeeded runs with no retry, fallback or loop traversal, over
 * finished runs.
 */
first_pass: Rate, retries: PerRun, fallbacks: PerRun, loop_traversals: PerRun, gate_wait: Waits, question_wait: Waits, 
/**
 * Run start to its terminal event.
 */
duration: Waits, spend: Spend, deliverable_missing: number, output_fields_missing: number, 
/**
 * Empty when the runs checked no goal.
 */
goal: Array<GoalStats>, 
/**
 * The findings and warnings the runs' attempts reported.
 */
findings: FindingStats, 
/**
 * Each baseline observation over the runs that compared it; empty
 * when the runs had no baseline check.
 */
baseline: Array<BaselineStats>, 
/**
 * The levels its runs' signed grades gave each criterion, one row per
 * comparable key ([`quality`]); empty when no run was graded.
 */
quality?: Array<QualityStats>, 
/**
 * What came into its finished runs from outside the playbook's flow
 * ([`interventions`]); absent when the version has no finished run.
 */
interventions?: InterventionStats, nodes: Array<NodeStats>, note?: string, 
/**
 * Runs of this version that were candidate trials (issue #192): the
 * version was a forward patch on trial when they ran.
 */
candidate_trials?: number, 
/**
 * Attempts per model actually used ([`UNREPORTED`] when a host said
 * nothing).
 */
models: { [key in string]: number }, 
/**
 * Attempts whose model differs from the node profile's primary model.
 */
model_mismatch: number, };

export type Comparison = { playbook: string, base: string, 
/**
 * `None` when no other version of the playbook has runs.
 */
against?: string, success_delta?: number, first_pass_delta?: number, retries_per_run_delta?: number, loops_per_run_delta?: number, median_duration_delta_ms?: number, cost_per_run_delta_usd?: number, 
/**
 * Nodes whose latest executor (profile or bundle digest) differs
 * between the two versions.
 */
executor_changes?: Array<ExecutorChange>, 
/**
 * How each criterion both versions graded under the same definition
 * moved.
 */
quality?: Array<QualityDelta>, };

export type StatsReport = { runs: number, 
/**
 * By playbook id, then version (oldest first).
 */
versions: Array<VersionStats>, compare?: Comparison, 
/**
 * [`NO_RUNS`] when no run matched.
 */
note?: string, };

export type UsageSource = "reported" | "estimated";

export type AgentUsage = { 
/**
 * Input tokens neither read from nor written to the prompt cache.
 */
input_tokens: number, 
/**
 * Output tokens, reasoning included.
 */
output_tokens: number, cache_read_tokens: number, cache_write_tokens: number, 
/**
 * The attempt's cost in US dollars as the CLI printed it, whatever its
 * basis ([`Self::cost_basis`] says whether anybody is billed for it).
 * A printed `0` is no figure and is left out: some CLIs print it on a
 * login they do not price, and a non-zero figure is no proof of money
 * spent either, since a CLI may price work a subscription covers.
 */
cost_usd?: number, source: UsageSource, 
/**
 * What `cost_usd` is: money billed, the list price of work a
 * subscription covers, or not known. Absent in a journal an older apb
 * wrote, and a value a newer apb wrote reads as unknown.
 */
cost_basis: CostBasis, };

export type CostBasis = "billed" | "subscription_equivalent" | "unknown";

export type CandidateTrial = { 
/**
 * The candidate version the run tried.
 */
version: string, 
/**
 * `running`; `promoted` or `rejected` once the run decided it; `wait`
 * or `needs_person` for a quality comparison it left open (or, once
 * that comparison was decided after the run, what the candidate's
 * trial record says now); `passed`
 * for a success that did not promote yet (`after_n_successes`,
 * `manual`); `undecided` for an end that judges nothing (a stop, a
 * replaced candidate).
 */
verdict: string, reason?: string, };

export type PauseBy = "operator" | "supervisor" | "engine";

export type PauseMode = "drain" | "now";

export type PauseCause = "quota" | "budget" | "billing";

export type PauseInfo = { reason: string, by: PauseBy, mode: PauseMode, 
/**
 * When the run went paused (the `run_paused` that opened the current
 * paused interval); absent while it is still `pausing`.
 */
since?: number, 
/**
 * When the run resumes on its own, epoch milliseconds.
 */
until?: number, keep_lock?: boolean, 
/**
 * The run still reads `running`: a pause is queued and a live driver is
 * draining toward it. A view overlay, never a journal status.
 */
pausing?: boolean, 
/**
 * Why the engine paused the run (a quota, the budget), derived from
 * the reason; absent for every other pause.
 */
cause?: PauseCause, };

export type RetryDue = { "kind": "now" } | { "kind": "at", at_ms: number, } | { "kind": "frozen", remaining_ms: number, };

export type RetryWait = { node: string, 
/**
 * The display number of the failed attempt; the delayed one follows it.
 */
attempt: number, 
/**
 * The retry number the delayed attempt runs as.
 */
retry: number, 
/**
 * The whole delay, in active run time.
 */
delay_ms: number, due: RetryDue, 
/**
 * The failure kind of the attempt that failed, when it was classified.
 */
failure_kind?: string, 
/**
 * Someone asked for it to start now (`retry_expedited`).
 */
expedited?: boolean, };

export type Released = { 
/**
 * The seq of its `drive_released`.
 */
seq: number, wake_at_ms: number, nodes: Array<string>, };

export type OnNoEstimate = "ask" | "pause" | "continue";

export type BudgetLimit = { tokens?: number, usd?: number, };

export type BudgetSource = "playbook" | "run" | "resume";

export type BudgetAmount = { tokens?: number, usd?: number, };

export type SpentDim = { 
/**
 * The sum the attempts (and the sub-playbook runs) reported.
 */
known: number, 
/**
 * Attempts that reported nothing in this dimension: unknown, never
 * zero.
 */
unknown_attempts: number, 
/**
 * The estimate for the unknown attempts (their node's median per
 * attempt), `None` when any of them has no estimate: the spent amount
 * is then unknown.
 */
imputed?: number, };

export type BudgetSpent = { tokens?: SpentDim, usd?: SpentDim, };

export type GateDecision = "paused" | "continued" | "waived" | "admitted_waived" | "failed" | "unknown";

export type GateBasis = "median" | "exhausted" | "no_estimate" | "unknown_spend" | "operator" | "unknown";

export type DimStatus = { 
/**
 * What the attempts reported.
 */
spent: number, 
/**
 * Attempts that reported nothing in this dimension.
 */
unknown_attempts: number, 
/**
 * The estimate for those attempts; absent when one has none.
 */
imputed?: number, 
/**
 * The limit minus the spent and imputed amounts; absent when unknown.
 */
remaining?: number, };

export type PausedAt = { node: string, 
/**
 * The list batch, for a list node.
 */
batch?: number, basis: GateBasis, need?: BudgetAmount, remaining?: BudgetAmount, };

export type BudgetStatus = { limit: BudgetLimit, on_no_estimate: OnNoEstimate, source?: BudgetSource, tokens?: DimStatus, usd?: DimStatus, 
/**
 * How often the budget was set (at start and at resumes).
 */
sets: number, 
/**
 * The gate pause holding the run, while it does.
 */
paused?: PausedAt, 
/**
 * A node a person let run once over the budget, until it does.
 */
waiver?: string, };

export type Spread<T> = { 
/**
 * How many samples; 0 for a declared figure.
 */
n: number, p50: T, low: T, high: T, kind: SpreadKind, };

export type SpreadKind = "iqr" | "min_max" | "single";

export type EstimateBasis = "history" | "declared" | "none";

export type Comparable = { 
/**
 * How a node's history was matched: [`ESTIMATE_KEY_VERSION`] (profile,
 * bundle and executor), or [`PROFILE_ONLY_KEY`] for a snapshot written
 * before it, which has no such field.
 */
key_version: number, 
/**
 * Runs of the same version and execution mode within the window.
 */
runs: number, succeeded: number, window: number, 
/**
 * Runs whose attempts reported no usage at all.
 */
runs_without_usage: number, attempts_without_usage: number, attempts_without_cost: number, 
/**
 * Per node, the comparable runs that bound it to another profile.
 */
profile_mismatch?: { [key in string]: number }, 
/**
 * Per node, the comparable runs that bound it to the same profile with
 * other skills (another bundle digest).
 */
bundle_mismatch?: { [key in string]: number }, 
/**
 * Per node, the comparable runs that bound it to the same profile and
 * skills with another executor (chain, tiers, or an override).
 */
executor_mismatch?: { [key in string]: number }, };

export type TimeEstimate = { basis: EstimateBasis, spread?: Spread<number>, 
/**
 * The median time succeeded runs waited for people (gates and
 * questions), included in the spread.
 */
human_wait_p50_ms?: number, };

export type SpendEstimate<T> = { basis: EstimateBasis, spread: Spread<T>, };

export type NodeSpread = { tokens?: Spread<number>, cost_usd?: Spread<number>, ms?: Spread<number>, };

export type AttemptMedian = { tokens?: number, cost_usd?: number, };

export type ItemsBasis = "inline" | "history" | "unknown";

export type ListEstimate = { 
/**
 * One item's spend over all its attempts (rounds and checks).
 */
per_item: NodeSpread, items?: number, items_basis: ItemsBasis, batch_ms_p50?: number, batch_size: number, };

export type NodeEstimate = { node: string, 
/**
 * The median number of visits per run.
 */
visits_p50: number, 
/**
 * One visit: what the budget gate weighs before the node.
 */
per_visit: NodeSpread, 
/**
 * All visits of a run: loops and retries as they happened.
 */
per_run: NodeSpread, per_attempt_p50: AttemptMedian, list?: ListEstimate, };

export type RunEstimate = { playbook: string, version: string, 
/**
 * `cli` or `host`.
 */
execution: string, comparable: Comparable, time: TimeEstimate, 
/**
 * Tokens over the estimated nodes; `None` when no node is estimated.
 */
tokens: SpendEstimate<number> | null, 
/**
 * What the estimated nodes cost when billed: the reported figures
 * whatever their basis (a subscription equivalent is priced like billed
 * work, so subscription history never admits billed work as free);
 * `None` when no comparable attempt reported a cost.
 */
cost_usd: SpendEstimate<number> | null, nodes: Array<NodeEstimate>, 
/**
 * Gated nodes with no spend sample: the run figures leave them out.
 */
unestimated: Array<string>, 
/**
 * Gated nodes the gate has no token figure for (those of
 * `unestimated` and those with cost samples only): a token limit
 * cannot weigh them, and the run's tokens leave them out.
 */
unestimated_tokens: Array<string>, 
/**
 * Gated nodes the gate has no cost figure for: a dollar limit cannot
 * weigh them, and the run's cost leaves them out.
 */
unestimated_cost: Array<string>, note?: string, };

export type Transition = "review" | "question" | "paused" | "finished" | "host_task" | "supervisor";

export type FinishOutcome = "succeeded" | "needs_look" | "failed" | "aborted";

export type NotifyTarget = { connector: string, account: string, function: string, to: string, };

export type NotifySent = { 
/**
 * `<kind>.<seq>`, e.g. `review.12`.
 */
transition: string, 
/**
 * `pending`, `confirmed`, `not_sent` or `unknown`.
 */
state: string, 
/**
 * When its latest try was recorded, epoch milliseconds.
 */
at: number, };

export type RunNotify = { active: boolean, target?: NotifyTarget, on: Array<Transition>, 
/**
 * The outcomes a `finished` notice is sent for; every outcome when
 * nothing narrows it.
 */
finished: Array<FinishOutcome>, 
/**
 * Where the subscription in force came from.
 */
source?: string, 
/**
 * Each transition notified, with what became of its latest try.
 */
sent: Array<NotifySent>, problems: Array<string>, };

export type MachineNotify = { 
/**
 * The machine's target; absent when none is configured.
 */
target?: NotifyTarget, 
/**
 * The transitions a run notifies about by default.
 */
on: Array<Transition>, 
/**
 * The run outcomes a `finished` notice covers by default (the
 * `policy.yaml` filters of the machine and the workspace).
 */
finished: Array<FinishOutcome>, 
/**
 * Whether a run of this workspace notifies without being asked (the
 * machine default, unless the project turned it off), for the
 * playbook the request names: the `policy.yaml` playbook filters
 * apply to it as they do at its start.
 */
default_on: boolean, 
/**
 * Why the machine or the project notify settings do not read.
 */
problem?: string, };

export type FieldState = "value" | "too_long" | "withheld" | "absent" | "invalid";

export type SearchField = { name: string, state: FieldState, 
/**
 * The value as the run has it, only in state `value`.
 */
value?: string, };

export type SearchFields = { "state": "indexed", fields: Array<SearchField>, } | { "state": "not_indexed" };

export type RunSummary = { run_id: string, playbook: string, status: string, started_ts: number, 
/**
 * Active milliseconds from `run_started` to the run's end (`run_finished`
 * or `run_aborted`), paused time left out: the same duration `apb stats`
 * counts. Absent while the run has not ended.
 */
duration_ms?: number, 
/**
 * Milliseconds a run that has not ended was inactive so far (paused,
 * or ended before a resume brought it back), so a listing can count its
 * active time up from `started_ts` without them. Absent once the run
 * ended (see `duration_ms`) and for a run that was never inactive.
 */
paused_ms?: number, progress?: ProgressSummary, parent_run?: string | null, continued_from?: string | null, superseded_by?: string | null, 
/**
 * The run has a drive claim and that claim's process is provably gone: the
 * journal still reads `running` because the only thing that writes a
 * terminal event is the drive loop that no longer exists. The single-run
 * surfaces (`run_status`, `apb doctor --run`) have answered this for a
 * while; a listing could not, so a killed driver looked healthy in a table.
 * `false` also covers "no drive claim at all", which is not a problem,
 * and a run that has ended ([`crate::run_view::RunView::driver_dead`]).
 */
driver_dead?: boolean, 
/**
 * The run's driver let go while a deferred retry waits: a waker
 * resumes it at `wake_at_ms` ([`crate::run_view::RunView::released`]).
 * Absent otherwise.
 */
released?: Released, 
/**
 * Events of a type this binary does not know, skipped when the journal
 * was read: a newer apb wrote them. Zero (and absent) for a journal this
 * binary reads in full.
 */
unknown_events?: number, 
/**
 * The run was a trial of the playbook's candidate version (issue #192),
 * with its verdict; absent for every other run.
 */
candidate_trial?: CandidateTrial, 
/**
 * The run's pause (issue #200): who paused it, why, since and until
 * when, and `pausing` while a live driver drains toward a queued pause.
 * Absent for a run that is neither paused nor pausing.
 */
pause?: PauseInfo, 
/**
 * Why the run needs a person's look: a baseline regression, or
 * findings or warnings its attempts reported. Absent when none.
 */
needs_look?: NeedsLook, 
/**
 * Where the run's playbook came from: `project` or `global`
 * (`run_provenance.origin`; a run without provenance is `project`).
 * Only in a filtered listing ([`list_runs_filtered`]).
 */
scope?: string, 
/**
 * The run's search fields; only in a filtered listing.
 */
search?: SearchFields, 
/**
 * The run's own `run.yaml` could not be read, with the error: the
 * run still lists with its journal facts, and only this run carries
 * the error.
 */
config_error?: string, };

export type RunListing = { runs: Array<RunSummary>, 
/**
 * Runs a field term dropped because they have no search fields; zero
 * when the filter has no field terms, because then nothing is left
 * out of `runs`.
 */
not_indexed: number, 
/**
 * Runs left out because a term names a field whose value is withheld
 * or too long (a non-match a query cannot probe).
 */
withheld: number, };

