export type LaunchPolicy = "allow" | "ask" | "deny";

export type LaunchRecord = { 
/**
 * What was launched: `start`, `trial`, `execute_plan`, `eval`,
 * `resume`, `resume_all`, `continue_from` or `child`.
 */
kind: string, 
/**
 * Who launched it: `agent_mcp`, `agent_mcp:<client>`, `run_step:mcp`,
 * `run_step:cli`, `cli_terminal`, `cli`, `dashboard`, `engine:<by>`,
 * or for a child `child_of:<run id>`.
 */
initiator: string, 
/**
 * How an `ask` or `deny` launch was confirmed: `terminal_prompt`,
 * `cli_flag`, `host_relayed`, `dashboard`, `forwarded:<kind>`;
 * absent for an `allow` launch.
 */
confirmation?: string, 
/**
 * The effective policy when it was admitted.
 */
policy: LaunchPolicy, 
/**
 * The settings that produced it.
 */
sources: Array<string>, 
/**
 * What the run may spend on (`crate::billing`): the bases the settings
 * allowed and the agents and bases a person confirmed. Absent in a
 * record an older apb wrote; such a run is checked against the
 * settings in force at each spawn.
 */
billing?: BillingRecord, };

export type BillingRecord = { 
/**
 * The bases the settings allowed for every agent when the run was
 * admitted.
 */
allowed: Array<CostBasis>, 
/**
 * The agents and bases a person confirmed.
 */
confirmed: Array<BillingEntry>, 
/**
 * How the confirmation was given (`terminal_prompt`, `cli_flag`,
 * `host_relayed`, `dashboard_nonce`, `forwarded:<kind>`); absent when
 * nothing needed one.
 */
confirmation?: string, 
/**
 * The settings that decided it.
 */
sources: Array<string>, };

export type BillingEntry = { agent: string, basis: CostBasis, };

export type ExecutionRef = { node: string, ordinal: number, ended_seq?: number, };

export type ListVisitRef = { node: string, started_seq: number, };

export type ResultItem = { visit: ListVisitRef, id: string, };

export type ResultPart = { "kind": "output" } | { "kind": "fields" } | { "kind": "file", scope: string, path: string, };

export type ResultRef = { execution: ExecutionRef, 
/**
 * The list item, for a result one item settled.
 */
item?: ResultItem, settlement_seq: number, part: ResultPart, 
/**
 * The attempt id (the seq of its `attempt_started`) that produced the
 * result; absent for work that spawned no attempt (a finish without a
 * prompt, a sub-playbook node, a cache hit).
 */
produced_by_attempt?: number, };

export type ResultScope = "workspace" | "run";

export type ResultFormat = "text" | "records";

export type EntryPart = "output" | "fields" | "file";

export type OmissionReason = "binary_not_supported" | "hard_link" | "link" | "match_limit" | "non_utf8_path" | "not_found" | "not_regular_file" | "read_limit" | "scenario_run" | "scrub_unavailable" | "secret_shaped" | "storage_limit" | "too_large" | "unreadable" | "unknown";

export type IncompleteReason = "enumeration_limit" | "match_limit" | "read_limit" | "storage_limit" | "unknown";

export type OutputOmitted = "run_limit" | "snapshot_limit" | "scrub_unavailable" | "unknown";

export type OmittedItem = { part?: EntryPart, scope?: ResultScope, path?: string, reason: OmissionReason, };

export type OmittedMore = { more: number, reasons: { [key in OmissionReason]?: number }, };

export type SnapshotOmission = OmittedItem | OmittedMore;

export type SnapshotSubject = { node: string, execution: number, 
/**
 * The seq of the list visit's `list_started`, for an item snapshot.
 */
visit_seq?: number, item?: string, 
/**
 * The attempt id (the seq of its `attempt_started`); absent for work
 * that spawned no attempt.
 */
attempt?: number, };

export type SnapshotProvenance = { 
/**
 * The node was a cache hit: the bytes are the restored ones.
 */
cache_hit: boolean, 
/**
 * `HEAD` of the tree at capture; absent off git.
 */
head?: string, 
/**
 * The seq of the execution's `artifacts_committed`, when it committed.
 */
commits_seq?: number, };

export type SnapshotEntry = { part: EntryPart, 
/**
 * For a file entry.
 */
scope?: ResultScope, 
/**
 * For a file entry: relative to its scope root, `/`-separated, scrubbed.
 */
path?: string, 
/**
 * Bytes of the stored (scrubbed) text.
 */
size: number, 
/**
 * `sha256:<hex>` of the stored bytes.
 */
digest: string, 
/**
 * The secret scrub changed the text; nothing of the original is kept.
 */
redacted: boolean, format: ResultFormat, 
/**
 * For an entry declared `format: records` whose text is not a package
 * ([`crate::records::parse`]): the first problem. The entry is then
 * stored as `format: text`.
 */
records_invalid?: string, };

export type ResultStamp = { snapshot_id: string, entries: number, bytes: number, omitted?: number, incomplete?: boolean, };

export type Verified = "ok" | "missing" | "corrupt";

export type EntryView = { 
/**
 * `output`, `fields` or `file:<scope>:<percent-encoded path>`, built
 * from the path as shown.
 */
entry: string, part: EntryPart, scope?: ResultScope, path?: string, 
/**
 * The size and digest of the text as served: the stored ones unless
 * the run redactor changes the text now. Absent when the object is
 * missing or no longer matches: nothing verifies the stored ones, and
 * next to a secret known only now they would confirm a guess.
 */
size?: number, digest?: string, redacted: boolean, 
/**
 * The run redactor changes this entry's text or path now: a secret
 * became known after capture.
 */
redacted_on_read?: boolean, format: ResultFormat, };

export type ResultRow = { execution: ExecutionRef, item?: ResultItem, 
/**
 * The seq of the `node_finished` or `list_item_settled` carrying the
 * stamp.
 */
settlement_seq: number, produced_by_attempt?: number, 
/**
 * That attempt's number, as its `attempt_started` counts it (the
 * number people read; the id above is a journal seq).
 */
attempt_number?: number, 
/**
 * The settlement's status (`succeeded`, `failed`, `timed_out`) or an
 * item's state.
 */
status: string, snapshot_id: string, entries: Array<EntryView>, omitted: Array<SnapshotOmission>, incomplete?: IncompleteReason, output_omitted?: OutputOmitted, provenance: SnapshotProvenance, verified: Verified, };

export type LegacyRefRow = { execution: ExecutionRef, settlement_seq: number, scope: string, path: string, digest: string, };

export type NotStoredRow = { node: string, 
/**
 * The execution ordinal, 1-based.
 */
execution: number, item?: string, 
/**
 * `snapshot not stored: <why>`, scrubbed and clipped at capture.
 */
reason: string, };

export type ResultsView = { rows: Array<ResultRow>, legacy: Array<LegacyRefRow>, 
/**
 * Settlements of declared results whose snapshot was not stored (the
 * `result_capture_failed` diagnostics), so a missing row says why.
 */
not_stored: Array<NotStoredRow>, };

export type EntryContent = { text: string, 
/**
 * The digest of the whole text as served, `sha256:<hex>`: the stored
 * one unless the text was redacted on read.
 */
digest: string, 
/**
 * The byte length of the whole text as served; a reader pages
 * against it.
 */
size: number, 
/**
 * The byte range `[a, b)` of the served text this answer holds.
 */
range: [number, number], redacted_at_capture: boolean, redacted_on_read: boolean, };

export type LiveComparison = "same" | "differs" | "missing" | "unreadable" | "not_comparable";

export type EvidenceVerdict = "structurally_valid" | "unsupported" | "absence_ok" | "not_enough_data";

export type EvidenceFlag = "whole_record" | "short_span" | "self_citation" | "shared_record" | "no_shared_words";

export type CitedFragment = { ref: string, fragment: string, };

export type ViewSummary = { id: string, kind: string, complete: boolean, collector_complete?: boolean, records: number, };

export type ClaimRow = { id: string, verdict: EvidenceVerdict, 
/**
 * The fixed wording of the verdict.
 */
wording: string, text: string, problems: Array<string>, flags: Array<EvidenceFlag>, cites: Array<CitedFragment>, absence?: Array<string>, };

export type EvidenceRow = { node: string, item?: string, attempt_number: number, attempt?: number, session: string, closed: boolean, read_chars: number, budget_chars: number, 
/**
 * The bound snapshots.
 */
snapshots: Array<string>, 
/**
 * The session's views, without text.
 */
views: Array<ViewSummary>, 
/**
 * `false` until the attempt's claims were checked.
 */
checked: boolean, output_unsupported: boolean, problems: Array<string>, claims: Array<ClaimRow>, };

export type CommitAttempt = { 
/**
 * The attempt id (the seq of its `attempt_started`).
 */
id: number, 
/**
 * The attempt's number, as its `attempt_started` counts it.
 */
number: number, };

export type Pick = "last" | "first" | "all";

export type OutputState = "value" | "null" | "missing";

export type MissingReason = "not_run" | "not_succeeded" | "field_absent" | "not_json_object" | "truncated" | "item_not_passed" | "definition_unknown";

export type OutputsDefinition = "stored" | "current";

export type ProjectedItem = { id: string, state: OutputState, value?: unknown, reason?: MissingReason, 
/**
 * The item's settlement, when the journal has one in the visit.
 */
source?: ResultRef, };

export type ProjectedValue = { state: OutputState, value?: unknown, reason?: MissingReason, source: ResultRef, items?: Array<ProjectedItem>, };

export type ProjectedOutput = { name: string, pick: Pick, state: OutputState, 
/**
 * The value, for state `value`. With `pick: all` the array of every
 * candidate's value (`null` kept, missing ones left out); with an
 * `item_field` an object from item id to value.
 */
value?: unknown, reason?: MissingReason, 
/**
 * The result the value came from (`last` and `first`).
 */
source?: ResultRef, 
/**
 * `pick: all`: every candidate, in settlement order.
 */
values?: Array<ProjectedValue>, 
/**
 * An `item_field` source: every item of the picked execution.
 */
items?: Array<ProjectedItem>, };

export type RunOutputs = { 
/**
 * The run is finished: the values will not change unless the run is
 * revived or continued, which sets this back to false.
 */
final: boolean, 
/**
 * Which declaration the projection read.
 */
definition: OutputsDefinition, 
/**
 * Every declared output, in declaration order.
 */
outputs: Array<ProjectedOutput>, };

export type RunDetail = { run_id: string, playbook: string, version: string, run_status: RunStatus, 
/**
 * Why a failed run ended (`node \`x\`: reason`); null unless failed.
 */
failure_reason: string | null, 
/**
 * Whether a process really drives the run; null when nothing claims to.
 */
driver_alive: boolean | null, 
/**
 * Per-node reported status (`lost` and `interrupted` included).
 */
nodes: { [key in string]: string }, outputs: { [key in string]: string }, instruction: string | null, 
/**
 * The run's params as shown: every sensitive value (a param declared
 * secret, a secret-shaped name, a credential-shaped value) reads
 * `<redacted>`.
 */
params: { [key in string]: string }, 
/**
 * The names of the params whose value `params` hides.
 */
redacted_params: Array<string>, 
/**
 * The run's working tree (issue #67 item 8), once resolved; null means
 * the nodes run in the project root.
 */
worktree: string | null, 
/**
 * The run's playbook snapshot; null for very old runs without one.
 */
model: { id: string; name: string; nodes: PlaybookNode[]; edges: PlaybookEdge[]; defaults?: { on_failure?: string } | null } | null, layout: WfLayout | null, 
/**
 * What the journal proves about every node and edge of the
 * definitions the run executed, through the run's redactor; a string
 * when the run's text is withheld.
 */
graph: RunGraph | string | null, 
/**
 * The definition of the graph's shown segment (the latest known one):
 * what the run canvas draws so edge states match the bytes that ran;
 * null when no definition of the run is established.
 */
graph_model: { id: string; name: string; nodes: PlaybookNode[]; edges: PlaybookEdge[]; defaults?: { on_failure?: string } | null } | null, hooks: { [key in string]: string }, 
/**
 * Sub-runs started by a `playbook` node, one per `ChildRunStarted`.
 */
children: Array<ChildRun>, 
/**
 * The playbook's goal with each criterion's result (C1); absent for a
 * playbook without a goal.
 */
goal?: RunGoal, 
/**
 * The commits the run's nodes made on a git tree (C7); empty when none.
 */
commits?: Array<NodeCommits>, 
/**
 * Each publish node: the pinned target, the latest plan, whether a
 * consent is awaited, the push's ledger state and the result; empty
 * for a run without one.
 */
publish?: Array<PublishView>, 
/**
 * Unread events the run's connector inbox reads found lost to inbox
 * retention, one per distinct gap; empty when none.
 */
inbox_gaps?: Array<RunInboxGap>, 
/**
 * The human outcome: what the run did, what the engine checked, what
 * nobody checked, and what the attempts reported.
 */
outcome: OutcomeSummary, 
/**
 * The baseline check, each observation before and after; absent for a
 * playbook without one.
 */
baseline?: RunBaseline, 
/**
 * The findings and warnings the attempts reported; absent when none.
 */
notes?: RunNotes, 
/**
 * The declared run outputs projected from the journal; absent for a
 * playbook that declares none.
 */
run_outputs?: RunOutputs, 
/**
 * Each list node's visit with its items; empty for a run without a
 * list.
 */
lists?: Array<RunList>, 
/**
 * The candidate trial this run was (issue #192), with its verdict;
 * absent for every other run.
 */
candidate_trial?: CandidateTrial, 
/**
 * The known problems the run showed its agents and the ones it hid;
 * absent for a run whose playbook shows none.
 */
known_problems?: RunKnownProblems, 
/**
 * The run's launch authorization: who launched it, how an `ask` or
 * `deny` launch was confirmed, the policy and its sources. Absent for a
 * run an older apb started.
 */
launch?: LaunchRecord, 
/**
 * The run's pause (issue #200): who paused it, why, since and until
 * when, and `pausing` while a live driver drains toward a queued
 * pause. Absent for a run that is neither paused nor pausing.
 */
pause?: PauseInfo, 
/**
 * The nodes whose retry waits out its `retry_delay`, each with when it
 * is due (an absolute time, or frozen while the run is paused); empty
 * when none waits.
 */
retry_waits?: Array<RetryWait>, 
/**
 * The run's driver let go while only deferred retries were left: a
 * waker resumes it at `wake_at_ms`. Absent otherwise.
 */
released?: Released, 
/**
 * The run's budget: limits, spent and left per dimension, and the node
 * a budget pause holds it before. Absent for a run without a budget.
 */
budget?: BudgetStatus, 
/**
 * The run's notifications: whether they are on, where they go, about
 * what, what was sent, and why a subscription could not be used.
 * Absent for a run that never had a subscription.
 */
notify?: RunNotify, 
/**
 * The estimate the run started with (time, tokens, cost from comparable
 * runs). Absent for a run started before estimates, or a sub-run.
 */
estimate?: RunEstimate, 
/**
 * Each attempt's identity: the model apb requested, what a host
 * reported, the chain position and why a step was entered, against the
 * profile's primary model; empty before the first attempt.
 */
attempt_models?: Array<ExecutionIdentityView>, 
/**
 * How often a host followed the hints of the run's host attempts;
 * absent when no host attempt had one.
 */
hint_follow?: HintFollow, 
/**
 * What each isolated attempt's isolation held and did not (level,
 * backend, network, limits); empty for a run without one.
 */
isolation?: Array<AttemptIsolationRow>, 
/**
 * Each read-only node's check per attempt (tier, what it covered) and
 * the changes that failed it; empty for a run without one.
 */
read_only?: Array<ReadOnlyRow>, 
/**
 * The run is unattended (`apb run --unattended`, MCP and HTTP
 * `unattended: true`), from its write-once manifest: every wait without
 * a declared outcome fails it. Read-only; left out for an attended run.
 */
unattended?: boolean, 
/**
 * Progress and every open gate (reviews, questions, waits, supervisor):
 * the run page renders its panels from this, never from `events`.
 */
progress: ProgressSummary | null, answer: string | null, 
/**
 * Token usage the run's attempts reported; null when none did.
 */
usage: RunUsage | null, 
/**
 * Decision-model totals (issue #165 Part 4); absent when the run
 * journaled no decision. Each decision itself is a `decision_made` in
 * `events`.
 */
decisions?: RunDecisions, 
/**
 * Events of a type this binary does not know (a newer apb wrote them),
 * left out of `events`; 0 for a journal read in full.
 */
unknown_events: number, 
/**
 * "driven by apb X, resumed by apb Y": the binaries that drove the run,
 * from the versions its journal recorded; absent when none did.
 */
driven_by?: string, 
/**
 * Who executes the run's agent steps, from its manifest: `cli` (the
 * profiles' CLIs) or `host` (the host session's subagents). Read-only.
 */
execution: "cli" | "host", 
/**
 * A `cli` run whose steps fall back to host tasks when no CLI can start.
 */
execution_fallback: boolean, events: WfEvent[], 
/**
 * What the run and its live sub-playbook runs are ready for, each
 * action with the run id it acts on, from the same read as the rest.
 */
next_actions: RunActions, };

